import type { Vec } from './types';
import { displayTwips } from './display-values';

/** Float32 coefficients, signed integer twip translations and points. */
export interface DisplayMatrix {
  a: number;
  b: number;
  c: number;
  d: number;
  tx: number;
  ty: number;
}
export const DISPLAY_IDENTITY: Readonly<DisplayMatrix> = {
  a: 1,
  b: 0,
  c: 0,
  d: 1,
  tx: 0,
  ty: 0,
};
const f = Math.fround;
const add = (a: number, b: number) => f(f(a) + f(b));
const subtract = (a: number, b: number) => f(f(a) - f(b));
const multiply = (a: number, b: number) => f(f(a) * f(b));
const divide = (a: number, b: number) => f(f(a) / f(b));

/** Matrix products use nearest/ties-even, unlike DisplayObject position setters. */
function roundedTwip(value: number) {
  if (!Number.isFinite(value)) return 0;
  if (value >= 2147483648 || value <= -2147483648) return -2147483648;
  const lower = Math.floor(value),
    fraction = value - lower;
  return fraction < 0.5 ? lower : fraction > 0.5 ? lower + 1 : lower % 2 === 0 ? lower : lower + 1;
}
export function displayMatrixProduct(
  left: Readonly<DisplayMatrix>,
  right: Readonly<DisplayMatrix>,
): DisplayMatrix {
  return {
    a: add(multiply(left.a, right.a), multiply(left.c, right.b)),
    b: add(multiply(left.b, right.a), multiply(left.d, right.b)),
    c: add(multiply(left.a, right.c), multiply(left.c, right.d)),
    d: add(multiply(left.b, right.c), multiply(left.d, right.d)),
    tx: (roundedTwip(add(multiply(left.a, right.tx), multiply(left.c, right.ty))) + left.tx) | 0,
    ty: (roundedTwip(add(multiply(left.b, right.tx), multiply(left.d, right.ty))) + left.ty) | 0,
  };
}
export function displayMatrixPoint(matrix: Readonly<DisplayMatrix>, point: Vec): Vec {
  return {
    x: (roundedTwip(add(multiply(matrix.a, point.x), multiply(matrix.c, point.y))) + matrix.tx) | 0,
    y: (roundedTwip(add(multiply(matrix.b, point.x), multiply(matrix.d, point.y))) + matrix.ty) | 0,
  };
}

/** Declared integer twips, before any pixel conversion or raster padding. */
export interface DisplayRectangle {
  xMin: number;
  yMin: number;
  xMax: number;
  yMax: number;
}

/** Script bounds transform each corner with the same arithmetic as a display Point. */
export function displayMatrixRectangle(
  matrix: Readonly<DisplayMatrix>,
  rectangle: Readonly<DisplayRectangle>,
): DisplayRectangle {
  const points = [
    { x: rectangle.xMin, y: rectangle.yMin },
    { x: rectangle.xMin, y: rectangle.yMax },
    { x: rectangle.xMax, y: rectangle.yMin },
    { x: rectangle.xMax, y: rectangle.yMax },
  ].map((point) => displayMatrixPoint(matrix, point));
  return {
    xMin: Math.min(...points.map((point) => point.x)),
    yMin: Math.min(...points.map((point) => point.y)),
    xMax: Math.max(...points.map((point) => point.x)),
    yMax: Math.max(...points.map((point) => point.y)),
  };
}
export function inverseDisplayMatrix(matrix: Readonly<DisplayMatrix>): DisplayMatrix | null {
  const det = subtract(multiply(matrix.a, matrix.d), multiply(matrix.b, matrix.c));
  if (!(Math.abs(det) > 2 ** -23)) return null;
  return {
    a: divide(matrix.d, det),
    b: divide(matrix.b, -det),
    c: divide(matrix.c, -det),
    d: divide(matrix.a, det),
    tx: roundedTwip(
      divide(subtract(multiply(matrix.d, matrix.tx), multiply(matrix.c, matrix.ty)), -det),
    ),
    ty: roundedTwip(
      divide(subtract(multiply(matrix.b, matrix.tx), multiply(matrix.a, matrix.ty)), det),
    ),
  };
}
const fromPixels = (point: Vec): Vec => ({ x: displayTwips(point.x), y: displayTwips(point.y) });
const toPixels = (point: Vec): Vec => ({ x: point.x / 20, y: point.y / 20 });
const scaleMatrix = (scale: number): DisplayMatrix => ({
  ...DISPLAY_IDENTITY,
  a: f(scale),
  d: f(scale),
});

/**
 * Physical player pixels → event target local → stageX/Y → reference local.
 * Ruffle local_mouse_position rounds in device pixels before returning twips;
 * the two ActionScript Point conversions retain their own truncating writes.
 * No DOM reads, saved-design mutation or rounding at serialization time.
 */
export function displayMousePoint(
  physicalPixels: Vec,
  viewport: Readonly<DisplayMatrix>,
  target: Readonly<DisplayMatrix>,
  reference: Readonly<DisplayMatrix>,
): Vec {
  const inverseView = inverseDisplayMatrix(viewport);
  const inverseReference = inverseDisplayMatrix(reference);
  if (!inverseView || !inverseReference) return { x: NaN, y: NaN };
  const mouse = displayMatrixPoint(inverseView, fromPixels(physicalPixels));
  const virtualToDevice = scaleMatrix(viewport.a);
  const twipsToPixels = scaleMatrix(1 / 20);
  const devicePoint = displayMatrixPoint(
    displayMatrixProduct(twipsToPixels, virtualToDevice),
    mouse,
  );
  const localToDevice = displayMatrixProduct(
    displayMatrixProduct(virtualToDevice, twipsToPixels),
    target,
  );
  const local = displayMatrixPoint(
    inverseDisplayMatrix(localToDevice) ?? DISPLAY_IDENTITY,
    devicePoint,
  );
  const eventStage = displayMatrixPoint(target, fromPixels(toPixels(local)));
  return toPixels(displayMatrixPoint(inverseReference, fromPixels(toPixels(eventStage))));
}

import { expect, test } from 'bun:test';
import authored from '../src/game/data/field-display.json';
import { STARTER } from '../src/game/data/catalog';
import type { DisplayGeometryContent } from '../src/game/core/display-geometry';
import {
  fieldScriptBounds,
  fieldStageShapeHit,
  type FieldGeometrySource,
} from '../src/game/simulation/field-queries';
import { createTank } from '../src/game/simulation/tank';
import { spawnPickups } from '../src/game/simulation/pickups';
import { World, emptyInput } from '../src/game/simulation/world';
import { cacheEmptyField } from './fixtures/empty-field';

/** Synthetic fills qualify traversal/routing, never original field contours. */
const leaf = (
  xMin: number,
  yMin: number,
  xMax: number,
  yMax: number,
  filled = true,
): DisplayGeometryContent => ({
  kind: 'leaf',
  bounds: { xMin, xMax, yMin, yMax },
  hit: ({ x, y }) => filled && x * 20 >= xMin && x * 20 <= xMax && y * 20 >= yMin && y * 20 <= yMax,
});
function source(): FieldGeometrySource {
  const bounds = authored.shapes as Record<
    number,
    { xMin: number; yMin: number; xMax: number; yMax: number }
  >;
  const sprites = authored.sprites as Record<number, unknown[]>;
  return {
    authored(node) {
      const b = bounds[node.symbol];
      if (b) return leaf(b.xMin, b.yMin, b.xMax, b.yMax, false);
      if (sprites[node.symbol]?.length === 0) return { kind: 'empty' };
      throw new Error(`Unsupported fixture symbol ${node.symbol}`);
    },
    tutorial: () => leaf(-2000, -2000, 2000, 2000, false),
    actor: (node) => (node.children.length ? leaf(-200, -200, 200, 200) : { kind: 'empty' }),
    pickup: () => leaf(-20, -20, 20, 20),
    effect: (node) => (node.kind === 'carrier' ? { kind: 'empty' } : leaf(-100, -100, 100, 100)),
  };
}
const width = (world: World, geometry: FieldGeometrySource, field = world.field) => {
  const bounds = fieldScriptBounds(world, field, geometry)!;
  return (bounds.xMax - bounds.xMin) / 20;
};

test('live first/new field Script widths retain original authored and four-child setter controls', () => {
  const world = new World([], [], 31),
    geometry = source();
  expect(width(world, geometry)).toBe(1381.4);
  for (const [scale, expected] of [
    [0.5, 696],
    [1, 1391.9],
    [1.25, 1739.9],
    [2, 2783.8],
  ]) {
    world.fieldDisplays.setupChildren(world.field, scale);
    expect(width(world, geometry)).toBe(expected);
  }
  // Synthetic dynamic geometry stays within the mask extrema in these controls.
  // This is not a measurement of the original tutorial or complete native field.
});

test('field widths reread physical actor geometry after movement, raw-array replacement and explicit detach', () => {
  const world = new World([], [], 31),
    geometry = source(),
    tank = createTank(77, STARTER, 'enemy', 900, 0);
  world.attachActor(tank, world.field);
  const baseline = width(world, geometry);
  expect(baseline).toBe(1600.75);
  tank.dead = true;
  tank.alpha = 0;
  world.field.enemies = [];
  expect(width(world, geometry)).toBe(baseline);
  tank.x = 1200;
  expect(width(world, geometry)).toBe(1900.75);
  tank.displayChildren = [];
  expect(width(world, geometry)).toBe(1381.4);
  world.actorParents.detach(tank);
  expect(width(world, geometry)).toBe(1381.4);
});

test('each dynamic slot must resolve and contribute independently, including currently masked bottom artwork', () => {
  const world = new World([], [], 31),
    geometry = source();
  spawnPickups(world, { x: 1100, y: 0 }, 1);
  const pickup = world.pickups[0];
  pickup.rotation = 0; // Controlled rectangle orientation, independent of birth RNG.
  world.pickups = [];
  expect(width(world, geometry)).toBe(1791.75);
  world.pickupDisplays.remove(pickup, world.field);
  const effect = world.addCombatEffect({ x: 1200, y: 0 }, 'rocketTrail', {}, true);
  expect(width(world, geometry)).toBe(1895.75);
  // A point outside the source under-mask cannot see this synthetic effect fill.
  expect(fieldStageShapeHit(world, world.field, geometry, { x: 1475, y: 225 })).toBe(false);
  world.effectEngine.clear();
  expect(width(world, geometry)).toBe(1381.4);
  geometry.tutorial = (node) => leaf(30000, 0, 30000 + node.sourceFrame * 20, 20);
  expect(width(world, geometry)).toBe(2193.75);
  world.fieldDisplays.selectTutorial(world.field, 4);
  expect(width(world, geometry)).toBe(2196.75);
  expect(world.effectEngine.parent(effect)).toBeUndefined();
});

test('stage-space shape contact follows Main/World/root ancestry and rejects a detached receiver', () => {
  const world = new World([], [], 31),
    geometry = source(),
    tank = createTank(77, STARTER, 'enemy', 900, 0);
  world.attachActor(tank, world.field);
  expect(fieldStageShapeHit(world, world.field, geometry, { x: 1175, y: 225 })).toBe(true);
  expect(fieldStageShapeHit(world, world.field, geometry, { x: 900, y: 0 })).toBe(false);
  world.fieldDisplays.moveCurrent(world.field, { x: 50, y: -20 });
  const stage = world.actorParents.localToGlobal(tank, { x: 0, y: 0 });
  expect(fieldStageShapeHit(world, world.field, geometry, stage)).toBe(true);
  world.fieldDisplays.detach(world.field);
  const detached = world.actorParents.localToGlobal(tank, { x: 0, y: 0 });
  expect(detached).not.toEqual(stage);
  expect(fieldStageShapeHit(world, world.field, geometry, detached)).toBe(false);
  expect(fieldStageShapeHit(world, world.field, geometry, stage)).toBe(false);
});

test('queue flush and concrete bottom reparenting change the next query immediately without a cached population', () => {
  const world = new World([], [], 31),
    geometry = source(),
    old = world.field;
  world.player.life = 1;
  cacheEmptyField(world);
  world.jump({ x: 1, y: 0 });
  const next = world.transit!.next,
    before = width(world, geometry, old),
    effect = world.addCombatEffect({ x: 1500, y: 0 }, 'rocketTrail', {}, false, next);
  expect(width(world, geometry, old)).toBe(before);
  world.step(emptyInput());
  expect(width(world, geometry, old)).toBeGreaterThan(before);
  const nextWidth = width(world, geometry, next),
    layer = world.effectEngine.layer(next, 'bottom')!;
  world.effectEngine.register(layer);
  world.effectEngine.unregister('bottom');
  world.effectEngine.create(effect, 'bottom', old);
  expect(width(world, geometry, old)).toBe(before);
  expect(width(world, geometry, next)).toBeGreaterThan(nextWidth);
});

test('unsupported geometry fails explicitly instead of substituting the existing circle or declared-box hit', () => {
  const world = new World([], [], 31),
    geometry = source(),
    tank = createTank(77, STARTER, 'enemy', 900, 0);
  world.attachActor(tank, world.field);
  geometry.actor = () => {
    throw new Error('Unqualified actor artwork');
  };
  expect(() => width(world, geometry)).toThrow('Unqualified actor artwork');
  expect(() => fieldStageShapeHit(world, world.field, geometry, { x: 0, y: 0 })).toThrow(
    'Unqualified actor artwork',
  );
});

import { DEG } from '../core/math';

/** Linear transform only; translations do not change geometric stroke widths. */
export interface ContactMatrix {
  a: number;
  b: number;
  c: number;
  d: number;
}
export const CONTACT_IDENTITY: ContactMatrix = { a: 1, b: 0, c: 0, d: 1 };

export function contactTransform(angle: number, x = 1, y = x): ContactMatrix {
  const c = Math.cos(angle * DEG),
    s = Math.sin(angle * DEG);
  return { a: c * x, b: s * x, c: -s * y, d: c * y };
}

/** Inverse(child-to-parent) × Stage-to-parent. Excludes CSS/DPR scaling. */
export function descendContact(parent: ContactMatrix, child: ContactMatrix): ContactMatrix | null {
  const { a, b, c, d } = child,
    det = a * d - b * c;
  if (!Number.isFinite(det) || Math.abs(det) < 1e-9) return null;
  return {
    a: (d * parent.a - c * parent.b) / det,
    b: (-b * parent.a + a * parent.b) / det,
    c: (d * parent.c - c * parent.d) / det,
    d: (-b * parent.c + a * parent.d) / det,
  };
}

/** Ruffle geometric contact: a one-logical-stage-pixel minimum, in leaf units. */
export function contactStrokeWidth(authored: number, inverse: ContactMatrix) {
  return Math.max(authored, Math.hypot(inverse.a, inverse.b), Math.hypot(inverse.c, inverse.d));
}

import type { SwfClip } from '../assets/swf-clip';
import type { Field, Pickup, Tank } from '../core/types';
import type { FieldInstanceRead } from './field-display';
import { isArtwork, type EffectClip } from './registered-effects';
import type { World } from './world';

/** A transient population read, never an ownership registry or a geometric result. */
export interface AuthoredFieldPopulation extends Omit<FieldInstanceRead, 'children'> {
  readonly kind: 'authored';
  readonly children: readonly FieldPopulationNode[];
}
export interface TutorialFieldPopulation extends Omit<FieldInstanceRead, 'children'> {
  readonly kind: 'tutorial';
  readonly sourceFrame: number;
  readonly stopped: true;
  readonly children: readonly FieldPopulationNode[];
}
export interface PopulationTransform {
  readonly x: number;
  readonly y: number;
  readonly rotation: number;
  readonly scale: number;
  readonly alpha: number;
}
interface PositionedPopulation {
  readonly transform: Readonly<PopulationTransform>;
}
export interface ActorFieldPopulation extends PositionedPopulation {
  readonly kind: 'actor';
  readonly instance: Tank;
  readonly children: readonly Tank['displayChildren'][number][];
}
export interface PickupFieldPopulation extends PositionedPopulation {
  readonly kind: 'pickup';
  readonly instance: Pickup;
  readonly symbol: number;
  /** The existing owner supplies this retained tree; reading never initializes it. */
  readonly pose: SwfClip;
}
export interface EffectFieldPopulation extends PositionedPopulation {
  readonly kind: 'effect' | 'carrier';
  readonly instance: EffectClip;
  /** Generic artwork pose qualification/expansion remains the geometry provider's work. */
}
export type FieldPopulationNode =
  | AuthoredFieldPopulation
  | TutorialFieldPopulation
  | ActorFieldPopulation
  | PickupFieldPopulation
  | EffectFieldPopulation;

function transform(source: {
  x?: number;
  y?: number;
  rotation?: number;
  scale?: number;
  alpha?: number;
}): Readonly<PopulationTransform> {
  return Object.freeze({
    x: source.x ?? 0,
    y: source.y ?? 0,
    rotation: source.rotation ?? 0,
    scale: source.scale ?? 1,
    alpha: source.alpha ?? 1,
  });
}

/**
 * Merge the actual wrapper/actor/pickup/engine owners at their physical slots.
 * Run arrays, map coordinates, UIDs, dead/alpha flags and request contexts never
 * determine membership. Read again after any callback that can mutate displays.
 * This supplies population only: consumers still need qualified leaf geometry,
 * per-instance artwork, depth masks and separate hit/Script-width arithmetic.
 */
export function readFieldPopulation(world: World, field: Field): AuthoredFieldPopulation {
  world.fieldDisplays.requireResolvedGeometry(field);
  const state = world.fieldDisplays.read(field);
  const project = (node: FieldInstanceRead): AuthoredFieldPopulation | TutorialFieldPopulation => {
    const children: FieldPopulationNode[] = node.children.map(project);
    if (node.id === state.slots.actors.id)
      for (const instance of world.actorParents.owned(field))
        children.push(
          Object.freeze({
            kind: 'actor',
            instance,
            transform: transform(instance),
            children: Object.freeze([...instance.displayChildren]),
          }),
        );
    if (node.id === state.slots.life.id)
      for (const instance of world.pickupDisplays.owned(field)) {
        const retained = world.pickupDisplays.read(instance)!;
        children.push(
          Object.freeze({
            kind: 'pickup',
            instance,
            symbol: retained.symbol,
            pose: retained.clip.pose,
            transform: transform(instance),
          }),
        );
      }
    if (node.id === state.bottom.id) {
      const layer = world.effectEngine.layer(field, 'bottom');
      if (layer)
        for (const instance of world.effectEngine.owned(layer))
          children.push(
            Object.freeze({
              kind: isArtwork(instance) ? 'effect' : 'carrier',
              instance,
              transform: transform(instance),
            }),
          );
    }
    if (node.id === state.tutorial.id)
      return Object.freeze({
        ...node,
        kind: 'tutorial',
        sourceFrame: state.tutorial.sourceFrame,
        stopped: true,
        children: Object.freeze(children),
      });
    return Object.freeze({ ...node, kind: 'authored', children: Object.freeze(children) });
  };
  // A field root is1551; its1667 tutorial is a separate child identity.
  return project(state.root) as AuthoredFieldPopulation;
}

/** DisplayObject setters: truncating, saturating signed8.8 alpha and signed32 twips. */
export const displayAlpha = (value: number) => {
  const fixed = Math.trunc(value * 256) || 0;
  return Math.max(-32768, Math.min(32767, fixed)) / 256;
};
export const displayTwips = (value: number) => {
  const twips = Math.trunc(value * 20) || 0;
  return Math.max(-2147483648, Math.min(2147483647, twips));
};
export const displayPixel = (value: number) => displayTwips(value) / 20;

/** DisplayObject.rotation retains Number precision and normalizes its getter to ±180°. */
export const displayRotation = (value: number) => {
  const remainder = value % 360;
  return remainder < -180 ? remainder + 360 : remainder > 180 ? remainder - 360 : remainder;
};

